#include "SoilSimulation.h"
#include "WorldCore/ChunkState.h"
void USoilSimulation::SimulateChunk(UChunkState* C,float Days,float Temp){if(!C||Days<=0)return;for(FChunkCell& Cell:C->Cells){if(Cell.Water.Volume>0){const float In=FMath::Min(Cell.Water.Volume,Cell.Water.Volume*FMath::Clamp(InfiltrationRate*Days,0.0f,1.0f));Cell.Water.Volume-=In;Cell.SoilMoisture=FMath::Clamp(Cell.SoilMoisture+In*0.5f,0.0f,1.0f);}const float TF=FMath::Clamp((Temp+5.0f)/25.0f,0.1f,2.0f);Cell.SoilMoisture=FMath::Max(0.0f,Cell.SoilMoisture-FMath::Max(0.0f,EvaporationRate)*TF*Days);if(Cell.SoilMoisture>0.8f){const float P=(Cell.SoilMoisture-0.8f)*FMath::Max(0.0f,PercolationRate)*Days;Cell.SoilMoisture=FMath::Max(0.8f,Cell.SoilMoisture-P);}Cell.SoilNitrogen=FMath::Max(0.0f,Cell.SoilNitrogen-NutrientNitrogenLossPerDay*Days);Cell.SoilPhosphorus=FMath::Max(0.0f,Cell.SoilPhosphorus-NutrientPhosphorusLossPerDay*Days);Cell.SoilPotassium=FMath::Max(0.0f,Cell.SoilPotassium-NutrientPotassiumLossPerDay*Days);Cell.bIsDirty=true;}C->MarkDirty();}
void USoilSimulation::ApplyIrrigation(UChunkState* C,int32 I,float Mm){if(!C||!C->Cells.IsValidIndex(I)||Mm<=0)return;C->Cells[I].SoilMoisture=FMath::Clamp(C->Cells[I].SoilMoisture+Mm*0.001f,0.0f,1.0f);C->Cells[I].bIsDirty=true;C->MarkDirty();}
